@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings

<nav class="settings-sidebar" role="tablist" aria-label="Settings sections">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                role="tab"
                aria-selected="@(section == ActiveSection)"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 1rem;
    min-width: 200px;
    background: var(--bs-gray-100);
    border-right: 1px solid var(--bs-border-color);
    height: 100%;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border: none;
    background: transparent;
    border-radius: 0.5rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: var(--bs-body-color);
    text-align: left;
    transition: background-color 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: var(--bs-gray-200);
}

.sidebar-item.active {
    background: var(--bs-primary);
    color: white;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.2rem;
}

.sidebar-label {
    flex: 1;
}

