@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@using sv_0337a3558cd14350832d009a0927d52d.Services
@inject ISettingsService SettingsService

<div class="profile-section">
    <h3>Profile Settings</h3>

    @if (isLoading)
    {
        <p class="text-muted">Loading profile...</p>
    }
    else
    {
        <div class="avatar-preview mb-4">
            <div class="avatar-frame">
                @if (!string.IsNullOrEmpty(avatarUrl))
                {
                    <img src="@avatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">👤</div>
                }
            </div>
            <div class="avatar-url text-muted small mt-1">@avatarUrl</div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="displayName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
                Discard Changes
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="alert alert-success mt-3 fade show" role="alert">
                ✅ Profile saved successfully!
            </div>
        }
    }
</div>

@code {
    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private UserProfile? savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        bio = profile.Bio;
        avatarUrl = profile.AvatarUrl;
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
        showSuccess = false;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;
        var profile = new UserProfile(displayName, email, avatarUrl, bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        isSaving = false;
        showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@using sv_0337a3558cd14350832d009a0927d52d.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    <h3>Notification Preferences</h3>

    @if (isLoading)
    {
        <p class="text-muted">Loading preferences...</p>
    }
    else
    {
        <div class="mb-4">
            <h5>General</h5>

            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>

            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>

            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h5>Muted Channels</h5>
            @if (allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                @foreach (var channel in allChannels)
                {
                    var ch = channel;
                    <div class="form-check mb-1">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
                               checked="@mutedChannels.Contains(ch)"
                               @onchange="e => ToggleChannel(ch, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
                    </div>
                }
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Preferences")
        </button>

        @if (showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">
                ✅ Notification preferences saved!
            </div>
        }
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    // Representative set of channels for the UI
    private static readonly List<string> DefaultChannels =
        ["general", "announcements", "engineering", "design", "marketing", "support", "random"];

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        allChannels = DefaultChannels;
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        isSaving = false;
        showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@using sv_0337a3558cd14350832d009a0927d52d.Services

<div class="change-password-panel">
    <button class="btn btn-outline-secondary d-flex align-items-center gap-2"
            @onclick="ToggleExpanded"
            aria-expanded="@isExpanded">
        <span class="expand-icon">@(isExpanded ? "▾" : "▸")</span>
        Change Password
    </button>

    @if (isExpanded)
    {
        <div class="password-form mt-3 p-3 border rounded">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger py-2" role="alert">@errorMessage</div>
            }

            @if (showSuccess)
            {
                <div class="alert alert-success py-2" role="alert">✅ Password updated successfully!</div>
            }

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@isUpdating">
                @(isUpdating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? errorMessage;
    private bool isUpdating;
    private bool showSuccess;

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePasswordAsync()
    {
        errorMessage = null;
        showSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            errorMessage = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(newPassword))
        {
            errorMessage = "New password is required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        isUpdating = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            showSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isUpdating = false;
        }
    }
}

@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@using sv_0337a3558cd14350832d009a0927d52d.Services

<div class="active-sessions-table">
    <h5>Active Sessions</h5>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    @if (confirmingSessionId == session.Id)
                                    {
                                        <span class="d-inline-flex gap-1">
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeAsync(session.Id)">
                                                Confirm
                                            </button>
                                            <button class="btn btn-outline-secondary btn-sm" @onclick="CancelRevoke">
                                                Cancel
                                            </button>
                                        </span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }

    private string? confirmingSessionId;

    private void RequestRevoke(string sessionId) => confirmingSessionId = sessionId;
    private void CancelRevoke() => confirmingSessionId = null;

    private async Task ConfirmRevokeAsync(string sessionId)
    {
        confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

