            <input type="email" class="form-control" @bind="email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
                Discard Changes
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="alert alert-success mt-3 fade show" role="alert">
                ✅ Profile saved successfully!
            </div>
        }
    }
</div>

@code {
    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private UserProfile? savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        bio = profile.Bio;
        avatarUrl = profile.AvatarUrl;
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
        showSuccess = false;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;
        var profile = new UserProfile(displayName, email, avatarUrl, bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        isSaving = false;
        showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
