@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@using sv_0337a3558cd14350832d009a0927d52d.Services

<div class="change-password-panel">
    <button class="btn btn-outline-secondary d-flex align-items-center gap-2"
            @onclick="ToggleExpanded"
            aria-expanded="@isExpanded">
        <span class="expand-icon">@(isExpanded ? "▾" : "▸")</span>
        Change Password
    </button>

    @if (isExpanded)
    {
        <div class="password-form mt-3 p-3 border rounded">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger py-2" role="alert">@errorMessage</div>
            }

            @if (showSuccess)
            {
                <div class="alert alert-success py-2" role="alert">✅ Password updated successfully!</div>
            }

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@isUpdating">
                @(isUpdating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? errorMessage;
    private bool isUpdating;
    private bool showSuccess;

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePasswordAsync()
    {
        errorMessage = null;
        showSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            errorMessage = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(newPassword))
        {
            errorMessage = "New password is required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        isUpdating = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            showSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isUpdating = false;
        }
    }
}

