@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@using sv_0337a3558cd14350832d009a0927d52d.Services

<div class="active-sessions-table">
    <h5>Active Sessions</h5>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    @if (confirmingSessionId == session.Id)
                                    {
                                        <span class="d-inline-flex gap-1">
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeAsync(session.Id)">
                                                Confirm
                                            </button>
                                            <button class="btn btn-outline-secondary btn-sm" @onclick="CancelRevoke">
                                                Cancel
                                            </button>
                                        </span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }

    private string? confirmingSessionId;

    private void RequestRevoke(string sessionId) => confirmingSessionId = sessionId;
    private void CancelRevoke() => confirmingSessionId = null;

    private async Task ConfirmRevokeAsync(string sessionId)
    {
        confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

