+        </div>
+
+        <div class="mb-4">
+            <h5>Two-Factor Authentication</h5>
+            <div class="d-flex align-items-center gap-3">
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" id="twoFactor"
+                           checked="@twoFactorEnabled" disabled />
+                    <label class="form-check-label" for="twoFactor">Two-Factor Authentication</label>
+                </div>
+                <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-secondary")">
+                    @(twoFactorEnabled ? "Enabled" : "Disabled")
+                </span>
+            </div>
+        </div>
+
+        @if (lastPasswordChange.HasValue)
+        {
+            <div class="mb-4">
+                <p class="text-muted small">
+                    Last password change: @lastPasswordChange.Value.ToString("f")
+                </p>
+            </div>
+        }
+
+        <ActiveSessionsTable Sessions="sessions"
+                             CurrentSessionId="@sessions.FirstOrDefault()?.Id"
+                             OnRevoke="HandleRevokeSessionAsync" />
+    }
+</div>
+
+@code {
+    private bool isLoading = true;
+    private bool twoFactorEnabled;
+    private DateTime? lastPasswordChange;
+    private List<ActiveSession> sessions = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAsync();
+    }
+
+    private async Task LoadAsync()
+    {
+        isLoading = true;
+        var settings = await SettingsService.GetSecuritySettingsAsync();
+        twoFactorEnabled = settings.TwoFactorEnabled;
+        lastPasswordChange = settings.LastPasswordChange;
+        sessions = settings.Sessions;
+        isLoading = false;
+    }
+
+    private async Task HandleChangePasswordAsync((string Current, string New) args)
+    {
+        await SettingsService.ChangePasswordAsync(args.Current, args.New);
+    }
+
+    private async Task HandleRevokeSessionAsync(string sessionId)
+    {
+        await SettingsService.RevokeSessionAsync(sessionId);
+        sessions = sessions.Where(s => s.Id != sessionId).ToList();
+    }
+}
+

