@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@using sv_0337a3558cd14350832d009a0927d52d.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    <h3>Appearance Settings</h3>

    @if (isLoading)
    {
        <p class="text-muted">Loading appearance settings...</p>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="mb-4">
                    <h5>Theme</h5>
                    @foreach (var t in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{t}")" value="@t"
                                   checked="@(theme == t)"
                                   @onchange="() => theme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h5>Font Size</h5>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(fontSize == size)"
                                   @onchange="() => fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width: 250px;" @bind="language">
                        <option value="en">English</option>
                        <option value="es">Spanish</option>
                        <option value="fr">French</option>
                        <option value="de">German</option>
                        <option value="ja">Japanese</option>
                        <option value="zh">Chinese</option>
                    </select>
                </div>

                <div class="mb-4">
                    <h5>Compact Mode</h5>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Enable compact mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save")
                </button>

                @if (showSuccess)
                {
                    <div class="alert alert-success mt-3" role="alert">
                        ✅ Appearance settings saved!
                    </div>
                }
            </div>

            <div class="col-md-5">
                <h5>Preview</h5>
                <div class="preview-area @PreviewThemeClass" style="@PreviewStyle">
                    <div class="preview-header">
                        <strong>Settings Dashboard</strong>
                    </div>
                    <div class="preview-content">
                        <p>This is how your content will look with the selected settings.</p>
                        <button class="btn btn-sm @PreviewButtonClass">Sample Button</button>
                    </div>
                    <div class="preview-footer text-muted">
                        Theme: @theme · Font: @fontSize · Compact: @(compactMode ? "On" : "Off")
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;
        isLoading = false;
    }

    private string PreviewThemeClass => theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewButtonClass => theme == "Dark" ? "btn-outline-light" : "btn-primary";

    private string PreviewStyle
    {
        get
        {
            var fs = fontSize switch
            {
                "Small" => "0.85rem",
                "Large" => "1.15rem",
                _ => "1rem"
            };
            var padding = compactMode ? "0.5rem" : "1rem";
            return $"font-size: {fs}; padding: {padding};";
        }
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(theme, fontSize, language, compactMode));
        isSaving = false;
        showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

