.preview-area {
    border: 1px solid var(--bs-border-color);
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-header {
    padding: 0.5rem 0.75rem;
    border-bottom: 1px solid inherit;
}

.preview-light .preview-header {
    background: #f8f9fa;
    border-bottom-color: #dee2e6;
}

.preview-dark .preview-header {
    background: #181825;
    border-bottom-color: #45475a;
}

.preview-content {
    padding: 0.75rem;
}

.preview-footer {
    padding: 0.5rem 0.75rem;
    font-size: 0.8em;
    border-top: 1px solid;
}

.preview-light .preview-footer {
    border-top-color: #dee2e6;
}

.preview-dark .preview-footer {
    border-top-color: #45475a;
    color: #a6adc8 !important;
}

