@page "/settings"
@namespace sv_0337a3558cd14350832d009a0927d52d.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <div class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";

    private void SetActiveSection(string section) => activeSection = section;
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    margin: -1rem -1.5rem;
}

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    overflow-y: auto;
}

.avatar-preview {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.avatar-frame {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid var(--bs-border-color);
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bs-gray-200);
}

.avatar-img {
    width: 100%;
    height: 100%;
